integrationChange:
以下补丁只实施统一风场。坐标约定：产品世界 Y 向上；位置和有限差分步长使用场景米，时间为秒，phase 为弧度。若在 Blender 验证，先由既有导入矩阵转换 Z-up 到产品 Y-up，再计算本函数，不能直接交换风向分量。

一、新建 lib/capture-lawn-wind.ts：
```typescript
import * as THREE from 'three';

type Scalar = {value:number};
type Uniforms = {
  lawnResponse:Scalar; lawnPhase:Scalar; lawnRootY:Scalar;
};

export function advanceLawnWind(response:Scalar, phase:Scalar,
  seconds:number, speed:number):boolean {
  if (!Number.isFinite(seconds) || seconds<=0) return false;
  const w=Number.isFinite(speed)?THREE.MathUtils.clamp(speed,-12,12):0;
  const target=w*Math.abs(w)/(36+w*w);
  if (response.value===0 && target===0) {phase.value=0;return false;}
  const dt=Math.min(seconds,.2);
  response.value+=(target-response.value)*-Math.expm1(-dt/.22);
  if (target===0 && Math.abs(response.value)<.0001) response.value=0;
  phase.value=response.value===0?0:
    (phase.value+dt*(1.5+.32*Math.abs(w)))%(2*Math.PI);
  return true;
}

const header=`
uniform float lawnResponse;
uniform float lawnPhase;
uniform float lawnRootY;
vec3 lawnWorld(vec3 p) {
  #ifdef USE_INSTANCING
    return (modelMatrix * instanceMatrix * vec4(p,1.0)).xyz;
  #else
    return (modelMatrix * vec4(p,1.0)).xyz;
  #endif
}
float lawnBaseY() {
  #ifdef USE_INSTANCING
    return (modelMatrix * instanceMatrix * vec4(0.,0.,0.,1.)).y;
  #else
    return lawnRootY;
  #endif
}
vec3 lawnOffset(vec3 p,float root) {
  float h=clamp(p.y-root,0.,.09);
  float wave=.84+.16*sin(lawnPhase-dot(p.xz,vec2(1.7,.91)));
  float slope=lawnResponse*wave*min(.5,7.*h);
  return vec3(.9745552*h*slope,
    -h*(1.-sqrt(max(0.,1.-slope*slope))),.2241477*h*slope);
}
`;

export function attachLawnWind(material:THREE.Material,
  uniforms:Uniforms, surface:boolean) {
  const prior=material.onBeforeCompile;
  const key=material.customProgramCacheKey();
  material.onBeforeCompile=function(shader,renderer) {
    prior.call(this,shader,renderer);
    Object.assign(shader.uniforms,uniforms);
    shader.vertexShader=header+shader.vertexShader.replace(
      '#include <begin_vertex>',`
      #include <begin_vertex>
      mat3 lawnPositionBasis=mat3(modelMatrix);
      #ifdef USE_INSTANCING
        lawnPositionBasis=mat3(modelMatrix)*mat3(instanceMatrix);
      #endif
      transformed+=inverse(lawnPositionBasis)*
        lawnOffset(lawnWorld(transformed),lawnBaseY());
    `);
    if (surface) shader.vertexShader=shader.vertexShader.replace(
      '#include <beginnormal_vertex>',`
      #include <beginnormal_vertex>
      if (lawnResponse!=0.) {
        vec3 lp=lawnWorld(position);
        float lr=lawnBaseY();
        float e=.0002;
        vec3 lo=lawnOffset(lp,lr);
        mat3 J=mat3(
          vec3(1.,0.,0.)+(lawnOffset(lp+vec3(e,0.,0.),lr)-lo)/e,
          vec3(0.,1.,0.)+(lawnOffset(lp+vec3(0.,e,0.),lr)-lo)/e,
          vec3(0.,0.,1.)+(lawnOffset(lp+vec3(0.,0.,e),lr)-lo)/e);
        mat3 B=mat3(modelMatrix);
        #ifdef USE_INSTANCING
          B=mat3(modelMatrix)*mat3(instanceMatrix);
        #endif
        objectNormal=transpose(B)*transpose(inverse(J))*
          transpose(inverse(B))*objectNormal;
      }
    `);
  };
  material.customProgramCacheKey=()=>key+
    ':lawn-world-coherence-v2:'+(surface?'surface':'shadow');
}
```

二、lib/capture-grass.ts 的准确修改位置：
1. 保留 THREE import；删除从 `const shaderHeader` 到 `attachShader` 函数结束的旧实现，加入：
```typescript
import {attachLawnWind,advanceLawnWind} from './capture-lawn-wind.ts';
```
2. 将三个 `attachShader(...)` 调用逐一改为 `attachLawnWind(...)`，原有 uniforms、surface 参数及材质恢复逻辑保持不变。
3. 将返回对象中整个 `step` 方法替换为：
```typescript
step(seconds:number,speed:number):boolean {
  return restore.length>0 && advanceLawnWind(strength,phase,seconds,speed);
},
```

三、lib/capture-meadow.ts 的准确修改位置：
1. 增加相同 import，将整个旧 `patchMeadowWind` 函数替换为：
```typescript
function patchMeadowWind(mat:THREE.Material,amplitude:{value:number},
  phase:{value:number},surface=true) {
  attachLawnWind(mat,{
    lawnResponse:amplitude,lawnPhase:phase,lawnRootY:{value:rootY}
  },surface);
}
```
2. 在 `patchMeadowWind(material,amplitude,phase);` 后插入：
```typescript
const depthMaterial=new THREE.MeshDepthMaterial({
  depthPacking:THREE.RGBADepthPacking,side:THREE.DoubleSide
});
const distanceMaterial=new THREE.MeshDistanceMaterial({side:THREE.DoubleSide});
patchMeadowWind(depthMaterial,amplitude,phase,false);
patchMeadowWind(distanceMaterial,amplitude,phase,false);
```
3. 在 rebuild 中创建 `const mesh=new THREE.InstancedMesh(...)` 后插入；不修改原有 castShadow 策略：
```typescript
mesh.customDepthMaterial=depthMaterial;
mesh.customDistanceMaterial=distanceMaterial;
```
4. `exportSnapshot` 中创建 `const copy=new THREE.InstancedMesh(...)` 后也插入：
```typescript
copy.customDepthMaterial=depthMaterial;
copy.customDistanceMaterial=distanceMaterial;
```
5. 将返回对象的 `update` 替换为：
```typescript
update(camera:THREE.Camera,seconds=0,speed=0) {
  if(disposed)return false;
  const changed=rebuild(camera);
  const windy=advanceLawnWind(amplitude,phase,seconds,speed);
  return changed||windy;
},
```
6. dispose 中在 `material.dispose()` 旁增加 `depthMaterial.dispose();distanceMaterial.dispose();`。所有 exportSnapshot 仍遵循原有借用材质生命周期，不把实时 shader 风变形误称为已烘焙的静态导出。

不改动 createMeadowLayout、tuftGeometry、isMeadowPoint、clearance、实例矩阵、原 socket 随机序列、候选数组或 .285/.044 保留率。两个控制器必须收到相同的 delta-seconds/speed 序列并从相同初态启动；这里没有新增未知调用点或全局时钟。

